(function(){
  'use strict';
  let saved={},study,ctx,active=false,last=Date.now(),input=Date.now(),visible=!document.hidden;
  const api=window.GMFAssessment={};
  let mfCoordinator;const mfStamp=()=>({wall_ms:Date.now(),mono_ms:performance.now(),runtime_id:'as:'+study.session_id});
  async function syncMFExam(running){if(!mfCoordinator){const [{makePort},{SessionCoordinator}]=await Promise.all([import('../mind-flow/v3/host.mjs'),import('../mind-flow/v3/core/coordinator.mjs')]);mfCoordinator=new SessionCoordinator(makePort(LearningStore),'mf-v3');}if(running)await mfCoordinator.examStart('assessment:'+study.session_id,mfStamp());else await mfCoordinator.examEnd('assessment:'+study.session_id);}

  api.ready=(async()=>{await GMFShared.init();GMFShared.mount('assessment');saved=await LearningStore.getModule('assessment-run')||{};ctx=saved.state&&saved.state.screen!=='home'?saved.context:GMFShared.context;ctx=ctx||GMFShared.context;study=saved.study||GMFShared.session(ctx,'assessment');api.context={...ctx,session_id:study.session_id};await syncMFExam(saved.state?.screen==='exam');return saved.state||null;})();
  function warning(){let p=document.getElementById('gmf-save-warning');if(!p){p=document.createElement('p');p.id='gmf-save-warning';p.setAttribute('role','alert');document.body.append(p);}p.textContent=GMFShared.text('本地保存失败，请保持页面打开。','Local save failed. Keep this page open.');}
  function tick(){const now=Date.now();if(study&&active)PathlineSessions.credit(study,last,now,input,visible&&navigator.onLine);last=now;}
  api.restore=()=>api.ready;
  api.persist=async state=>{await api.ready;tick();saved={state,study,context:ctx};return LearningStore.commit('assessment-run',saved,null,study).catch(warning);};
  api.receive=async message=>{await api.ready;tick();if(message.kind==='gmf-assessment-activity'){const running=message.active===true;if(running!==active)await syncMFExam(running);active=running;if(message.interaction)input=Date.now();return;}
    if(message.kind!=='gmf-assessment-result')return;active=false;await syncMFExam(false);const p=message.payload;
    if(!p||!Array.isArray(p.answers)||!p.answers.length||p.answers.length>1000||p.answers.some(a=>!/^gmf-[a-f0-9]{64}$/.test(a.exercise_id)||typeof a.correct!=='boolean'))return;
    const event={schema_version:3,event_id:study.session_id+'-result',course_id:ctx.course_id,unit_id:null,topic_id:null,exercise_id:null,source:'Assessment',type:'ASSESSMENT',occurred_at:new Date().toISOString(),payload:{...p,session_id:study.session_id,active_seconds:study.active_seconds,launch_context:{...ctx},canonical_exercises:p.answers.map(a=>({exercise_id:a.exercise_id,original_question_id:a.question_id}))}};
    try{await LearningStore.commit('assessment-run',saved,event,study);}catch{warning();}
  };
  api.start=async()=>{await api.ready;study=GMFShared.session(GMFShared.context,'assessment');ctx=GMFShared.context;api.context={...ctx,session_id:study.session_id};input=last=Date.now();await syncMFExam(true);active=true;};
  const names={
    '检查识别内容':'Review recognized content','试卷标题':'Paper title','考试时长（分钟）':'Exam duration (minutes)','题干':'Question text','题目图片':'Question image','可选':'Optional','选项与正确答案':'Options and correct answer','添加选项':'Add option','删除此题':'Delete question','选择左侧圆点设为正确答案；未确认时保持空白。':'Select a circle to set the correct answer. Leave it blank until confirmed.','识别质量':'Recognition quality','可直接使用':'Ready to use','题号与顺序':'Question order','题干与选项':'Question text and options','已提取':'Extracted','你的确认优先':'Your confirmation comes first','AI 的结果只是草稿。只有你确认的内容会进入考试。':'AI produces a draft. Only confirmed content enters the exam.','生成考试':'Create exam','检查完成':'Review complete','自动保存已开启':'Autosave enabled','QUALITY CHECK':'内容检查','Draft':'草稿','EXAM READY':'考试已准备好','Great work — keep the five in sight.':'完成这次练习，继续稳步推进。','上传或粘贴图片':'Upload or paste an image','PNG、JPG 或剪贴板图片':'PNG, JPG or a clipboard image','撤销上一步':'Undo last change','未命名练习试卷':'Untitled practice set','Upload':'上传','Review':'回看','Take exam':'开始考试','Improve':'修正','Original interface · Student-built':'原 GiveMeFive 考试界面','V1.1 workspace':'练习工作区','EXAM COMPLETE':'考试已结束','Good start — now turn misses into points.':'回看这次错题，准备下一次练习。','Strong work — keep the momentum.':'完成这次练习，接下来回看结果。','Accuracy':'正确率','Answered':'已作答','unanswered':'题未作答','questions':'道题','questions to revisit':'道题需要回看','REVIEW':'错题回看','再做一次':'Try again','返回主界面':'Home','错题与未答题':'Incorrect and unanswered questions','检查并提交':'Review and submit','给题目加一面旗帜，方便交卷前返回；已选答案会保留。':'Flag a question to return before submitting. Your answer is preserved.','Close':'关闭','剩余时间':'Time remaining','题目目录':'Question directory','标记稍后检查':'Mark for review','已标记 · 点击取消':'Marked · unmark','旗帜会同步到题目目录，不影响答案':'Flags appear in the directory; answers stay unchanged','上一题':'Previous','下一题':'Next','提交考试':'Submit exam','提交考试？':'Submit exam?','提交后本次答案将不能修改。':'You cannot change answers after submitting.','已作答':'Answered','未作答':'Unanswered','已标记':'Marked','继续检查':'Continue reviewing','确认提交':'Confirm submission','你还有未作答或已标记的问题。':'You still have unanswered or marked questions.','选择或拖入试卷':'Choose or drop a paper','手动创建试卷':'Create manually','打开示例考试':'Open sample exam','返回主页':'Home','返回编辑':'Back to editor','开始考试':'Begin exam','你的练习考试已准备好':'Your practice exam is ready','开始后计时器会立即运行。你可以随时标记题目并返回检查。':'The timer starts immediately. Mark questions and return to review them.','系统先生成可编辑草稿，无法确认的内容交给你决定。':'Review the editable draft and resolve uncertain content.','或者':'or','上传试卷，检查 AI 识别结果，然后进入专注的 AP 风格考试。每一道题都由你最终确认。':'Import a paper, check recognition, then begin a focused AP practice exam. You confirm every question.','FROM PAPER TO PRACTICE':'从试卷到练习','Turn any practice set into a focused digital exam.':'把一份试卷，变成一次专注练习。','NEW EXAM':'创建考试','Import a practice set':'导入练习试卷','Exam':'考试','Time':'时间','Questions':'题目','Exam complete':'考试已结束','继续练习':'Practice again','重新开始':'Start again','查看错题':'Review mistakes','答对':'Correct','答错':'Incorrect','正确答案':'Correct answer','你的答案':'Your answer','暂存草稿':'Save draft','草稿已保存':'Draft saved','考试时长':'Exam duration','分钟':'minutes','删除题目':'Delete question','添加题目':'Add question','完成编辑':'Finish editing','未选择':'Not answered'
  };
  const originals=new WeakMap();let translating=false;
  function translate(){if(translating||!study)return;translating=true;const en=GMFShared.current.lang==='en',r=document.getElementById('root');if(r){const walker=document.createTreeWalker(r,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){if(n.parentElement.closest('textarea,input,script,style,.question-card,.review-question,.review-stem'))continue;let record=originals.get(n);if(!record||n.textContent!==record.out){record={raw:n.textContent,out:n.textContent};originals.set(n,record);}const raw=record.raw,trim=raw.trim();let out=names[trim];let translated=raw;
      if(out){const chinese=/[\u3400-\u9fff]/.test(trim);translated=raw.replace(trim,en?(chinese?out:trim):(chinese?trim:out));}
      else if(en){translated=raw.replace(/第 (\d+) 题，共 (\d+) 题/g,'Question $1 of $2').replace(/(\d+) 道选择题 · (\d+) 分钟 · 自动判分/g,'$1 MCQ · $2 minutes · automatic scoring').replace(/你的答案：/g,'Your answer: ').replace(/正确答案：/g,'Correct answer: ').replace(/未作答/g,'Unanswered').replace(/已作答/g,'Answered').replace(/题已标记/g,'marked').replace(/用时/g,'Time used');}
      else{translated=raw.replace(/QUESTION (\d+)/g,'第 $1 题').replace(/(\d+) unanswered/g,'$1 题未作答').replace(/(\d+) questions/g,'$1 道题');}
      record.out=translated;if(n.textContent!==translated)n.textContent=translated;}}translating=false;}
  api.recordBlocker=async question=>{await api.ready;if(!crypto.subtle)throw Error('AS 题目稳定关联需要 HTTPS');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({stem:question.stem,options:question.options,image:question.image||null}))),canonical='gmf-'+Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');const {makePort}=await import('../mind-flow/v3/host.mjs'),{upsertBlocker}=await import('../mind-flow/v3/core/entities.mjs');await makePort(LearningStore).transact('mf-v3',row=>{const out=upsertBlocker(row.blockers,{blocker_id:crypto.randomUUID(),title:'回看 AS 题目 '+question.id,context:{...ctx,source:'Assessment',return_to:new URL('./#question/'+encodeURIComponent(question.id)+'/'+canonical,location.href).href},question_ref:{namespace:'fusion-assessment-sha256',question_id:canonical}});const i=row.blockers.findIndex(x=>x.blocker_id===out.blocker.blocker_id);if(i<0)row.blockers.push(out.blocker);else row.blockers[i]=out.blocker;return row;});};
  api.links=()=>{const r=document.getElementById('root');let links=document.getElementById('gmf-result-links');if(!r?.querySelector('.results-shell,.results-hero')){links?.remove();return;}if(!links){links=document.createElement('div');links.id='gmf-result-links';links.className='gmf-return-actions';r.insertAdjacentElement('afterend',links);}links.innerHTML=`<a href="${GMFShared.esc(GMFShared.safeReturn(ctx.return_to))}">${GMFShared.text('返回 Pathline','Return to Pathline')}</a><a href="${GMFShared.esc(GMFShared.url('mindflow',ctx))}">${GMFShared.text('进入 Mind Flow 修正','Repair in Mind Flow')}</a><a href="${GMFShared.esc(GMFShared.url('progress',ctx))}">Progress</a>`;const questions=saved.state?.questions||[],answers=saved.state?.answers||{};const missed=questions.filter(q=>answers[q.id]!==q.correctAnswer);for(const [i,q] of missed.entries()){const b=document.createElement('button');b.textContent='记录问题 · '+(q.id||'AS');b.onclick=async()=>{try{await api.recordBlocker(q);b.textContent='已保存到 Mind Flow';b.disabled=true;}catch{warning();}};links.append(b);const article=r.querySelectorAll('.review-list article')[i];if(article)article.id='question-'+q.id;}if(location.hash.startsWith('#question/')){const parts=location.hash.split('/'),id=decodeURIComponent(parts[1]||''),question=questions.find(q=>String(q.id)===id),target=document.getElementById('question-'+id);if(question&&target&&crypto.subtle&&!api.returnChecked){api.returnChecked=true;crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({stem:question.stem,options:question.options,image:question.image||null}))).then(d=>{const actual='gmf-'+Array.from(new Uint8Array(d),v=>v.toString(16).padStart(2,'0')).join('');if(actual===parts[2])target.scrollIntoView({block:'center'});else{const p=document.createElement('p');p.textContent='当前试卷已变化，原题记录仍保留在 MF。请先恢复对应 AS 备份。';links.append(p);}});}}};
  api.ready.then(()=>{const r=document.getElementById('root');const observer=new MutationObserver(()=>{translate();api.links();});observer.observe(r,{childList:true,characterData:true,subtree:true});translate();});
  document.addEventListener('gmf-preferences',()=>{translate();api.links();});
  document.addEventListener('visibilitychange',()=>{tick();visible=!document.hidden;last=input=Date.now();if(saved.state)api.persist(saved.state);});
  addEventListener('pagehide',()=>{tick();if(saved.state)api.persist(saved.state);});
  setInterval(()=>{tick();if(active&&saved.state)api.persist(saved.state);},5000);
})();
